test('batches 11 through 1000 Custom Elements register', async ({ page }) => {
  await page.goto('/playground/elements')
  const tags = generatedComponents.map((entry) => entry.tag)
  const registered = await page.evaluate((names) => names.every((name) => Boolean(customElements.get(name))), tags)
  expect(registered).toBe(true)
})

for (const component of generatedComponents) {
  test(`${component.name} documentation preview renders`, async ({ page }) => {
    await page.goto(`/components/${component.slug}`)
    await expect(page.locator(`[data-uv-component="${component.name}"]`)).toBeVisible()
  })
}
